/**
 * The model recommendation per instrument (`investments/domain/plan.py`).
 *
 * The legacy name `plan` is kept for migration compatibility. The value is generated by the connected
 * model from research, thesis health, portfolio construction and strategy. It is not the owner's
 * decision and it never places an order.
 *
 * | value       | held label (PL)  | watched (PL) | held only |
 * |-------------|------------------|--------------|-----------|
 * | `buy_asap`  | dokup asap       | kup asap     | no        |
 * | `buy`       | dokup            | kup          | no        |
 * | `hold`      | trzymaj          | czekam       | no        |
 * | `reduce`    | redukuj          | -            | yes       |
 * | `exit_asap` | pozbądź się asap | -            | yes       |
 *
 * A reduce / exit recommendation is stale when the position is gone or was reopened after generation.
 * Views then emit it as null; the stored value stays for auditability.
 *
 * `plan_label` reads the UI language from settings in Python (`tr`, I/O); here the language is a
 * parameter, so the function stays pure.
 */

import type { DateTime } from "../../dates.js";
import type { Holding, RealizedTrade } from "./snapshot.js";
import type { CalendarDate } from "./values.js";

export const PLAN_VALUES = Object.freeze([
  "buy_asap",
  "buy",
  "hold",
  "reduce",
  "exit_asap",
] as const);
export type PlanValue = (typeof PLAN_VALUES)[number];

export const HELD_ONLY_PLANS: ReadonlySet<string> = new Set(["reduce", "exit_asap"]);
export const BUY_PLANS: ReadonlySet<string> = new Set(["buy", "buy_asap"]);

/** Polish labels of a held instrument's plan (the dashboard shows the same). */
export const PLAN_LABEL_HELD: Readonly<Record<string, string>> = Object.freeze({
  buy_asap: "dokup asap",
  buy: "dokup",
  hold: "trzymaj",
  reduce: "redukuj",
  exit_asap: "pozbądź się asap",
});

/** Polish labels of a watched (not held) instrument's plan. */
export const PLAN_LABEL_WATCHED: Readonly<Record<string, string>> = Object.freeze({
  buy_asap: "kup asap",
  buy: "kup",
  hold: "czekam",
});

/** English labels of a held instrument's plan (the dashboard's `PLAN_HELD_L`). */
export const PLAN_LABEL_HELD_EN: Readonly<Record<string, string>> = Object.freeze({
  buy_asap: "buy more asap",
  buy: "buy more",
  hold: "hold",
  reduce: "reduce",
  exit_asap: "exit asap",
});

/** English labels of a watched instrument's plan. */
export const PLAN_LABEL_WATCHED_EN: Readonly<Record<string, string>> = Object.freeze({
  buy_asap: "buy asap",
  buy: "buy",
  hold: "wait",
});

export function isPlan(value: unknown): value is PlanValue {
  return typeof value === "string" && (PLAN_VALUES as readonly string[]).includes(value);
}

/**
 * The plan as views and checks use it: a held-only plan (reduce / exit_asap) is null when the
 * instrument is not held, or when `planAt` (UTC) falls on a day before `opened` (the day the current
 * holding last reopened from zero, `openedOn`). `held = null` (unknown) keeps it; a plan written on the
 * opening day counts as current.
 */
export function effectivePlan(
  plan: string | null,
  options: {
    readonly held: boolean | null;
    readonly planAt?: DateTime | null;
    readonly opened?: CalendarDate | null;
  },
): PlanValue | null {
  if (plan === null || !isPlan(plan)) return null;
  if (HELD_ONLY_PLANS.has(plan)) {
    const { held, planAt = null, opened = null } = options;
    if (held === false) return null;
    // Python `plan_at.date()`: the date in the timestamp's own zone, as given.
    if (held && planAt !== null && opened !== null && planAt.date < opened) return null;
  }
  return plan;
}

/**
 * The day the current holding of one instrument last reopened from zero: the first buy after the
 * quantity was last 0 (for a never-closed position, its first lot). `holdings`: its `Holding` rows
 * (any accounts); `realized`: `RealizedTrade` rows (other instruments are ignored). A closed lot part
 * held on the day before the candidate date (opened before it, closed on or after it) means the
 * position was not at zero: the date moves back to its open date, until no closed part bridges the
 * gap. Null without open lots.
 */
export function openedOn(
  holdings: Iterable<Holding>,
  realized: Iterable<RealizedTrade> = [],
): CalendarDate | null {
  const rows = [...holdings];
  // ISO date strings: the smallest one is the earliest date (min over dates, not numbers)
  const dates = rows.flatMap((h) => h.lots.map((lot) => lot.openDate)).sort();
  let start = dates[0];
  if (start === undefined) return null;
  const ids = new Set(rows.map((h) => h.instrumentId));
  const spans = [...realized]
    .filter((r) => ids.has(r.instrumentId))
    .map((r) => [r.openDate, r.closeDate] as const)
    .sort((a, b) =>
      a[0] !== b[0] ? (a[0] < b[0] ? -1 : 1) : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0,
    );
  let moved = true;
  while (moved) {
    moved = false;
    for (const [opened, closed] of spans) {
      if (opened < start && start <= closed) {
        start = opened;
        moved = true;
      }
    }
  }
  return start;
}

export type PlanLanguage = "pl" | "en";

/** Label of `plan` for a held or a watched instrument in `lang` (null: no plan / not allowed). */
export function planLabel(
  plan: string | null,
  options: { readonly held: boolean; readonly lang: PlanLanguage },
): string | null {
  if (plan === null) return null;
  const labels = options.held
    ? options.lang === "pl"
      ? PLAN_LABEL_HELD
      : PLAN_LABEL_HELD_EN
    : options.lang === "pl"
      ? PLAN_LABEL_WATCHED
      : PLAN_LABEL_WATCHED_EN;
  return Object.hasOwn(labels, plan) ? (labels[plan] as string) : null;
}
